137	const findLastContentLine = (
138	  buffer: pkg.IBuffer,
139	  startLine: number,
140	): number => {
141	  const lineCount = buffer.length;
142	  for (let i = lineCount - 1; i >= startLine; i--) {
143	    const line = buffer.getLine(i);
144	    if (line && line.translateToString(true).length > 0) {
145	      return i;
146	    }
147	  }
148	  return -1;
149	};
