151	const getFullBufferText = (terminal: pkg.Terminal, startLine = 0): string => {
152	  const buffer = terminal.buffer.active;
153	  const lines: string[] = [];
154	
155	  const lastContentLine = findLastContentLine(buffer, startLine);
156	
157	  if (lastContentLine === -1 || lastContentLine < startLine) return '';
158	
159	  for (let i = startLine; i <= lastContentLine; i++) {
160	    const line = buffer.getLine(i);
161	    if (!line) {
162	      lines.push('');
163	      continue;
164	    }
165	
166	    let trimRight = true;
167	    if (i + 1 <= lastContentLine) {
168	      const nextLine = buffer.getLine(i + 1);
169	      if (nextLine?.isWrapped) {
170	        trimRight = false;
171	      }
172	    }
173	
174	    const lineContent = line.translateToString(trimRight);
175	
176	    if (line.isWrapped && lines.length > 0) {
177	      lines[lines.length - 1] += lineContent;
178	    } else {
179	      lines.push(lineContent);
180	    }
181	  }
182	
183	  return lines.join('\n');
184	};
