186	const writeBufferToLogStream = (
187	  terminal: pkg.Terminal,
188	  stream: fs.WriteStream,
189	  startLine = 0,
190	): number => {
191	  const buffer = terminal.buffer.active;
192	  const lastContentLine = findLastContentLine(buffer, startLine);
193	
194	  if (lastContentLine === -1 || lastContentLine < startLine) return startLine;
195	
196	  for (let i = startLine; i <= lastContentLine; i++) {
197	    const line = buffer.getLine(i);
198	    if (!line) {
199	      stream.write('\n');
200	      continue;
201	    }
202	
203	    let trimRight = true;
204	    if (i + 1 <= lastContentLine) {
205	      const nextLine = buffer.getLine(i + 1);
206	      if (nextLine?.isWrapped) {
207	        trimRight = false;
208	      }
209	    }
210	
211	    const lineContent = line.translateToString(trimRight);
212	    const stripped = stripAnsi(lineContent);
213	
214	    if (line.isWrapped) {
215	      stream.write(stripped);
216	    } else {
217	      if (i > startLine) {
218	        stream.write('\n');
219	      }
220	      stream.write(stripped);
221	    }
222	  }
223	
224	  // Ensure it ends with a newline if we wrote anything and the next line is not wrapped
225	  if (lastContentLine >= startLine) {
226	    const nextLine = terminal.buffer.active.getLine(lastContentLine + 1);
227	    if (!nextLine?.isWrapped) {
228	      stream.write('\n');
229	    }
230	  }
231	
232	  return lastContentLine + 1;
233	};
